with parsed as (select id, plan, effective_from, currency, tier_limits, aggregate(tier_prices, cast(0 as double), (acc, p) -> acc + p, acc -> round(acc / size(tier_prices), 2)) as avg_tier_price, element_at(tier_prices, 1) as entry_price, zip_with(tier_prices, discounts, (p, d) -> round(p * (1 - d), 2)) as net_prices from price_tiers) select case when entry_price >= 28 then 'HIGH' else 'LOW' end as entry_price_tier, count_if(plan = 'basic') as basic_events, percentile_approx(avg_tier_price, array(0.25, 0.5, 0.75)) as avg_tier_price_quartiles, sort_array(collect_set(plan)) as plan_list from parsed group by entry_price_tier order by entry_price_tier desc;
